  1	// src/lib/rechner/bestandsanlage.js
  2	//
  3	// Bewertung laufender PV-Anlagen (Zweitmarkt) nach dem Ertragswert- bzw.
  4	// DCF-Verfahren. Reine Logik ohne React; Standardwerte aus
  5	// src/lib/invest/markt.js (BESTAND, ERLOESE, PHASEN, FREIFLAECHE).
  6	//
  7	// Methodik (bewusst einfach und offen gelegt):
  8	//  - Cashflow je Kalenderjahr ab BESTAND.bewertungsjahr, unverschuldet,
  9	//    vor Ertragsteuern
 10	//  - Erzeugung: gemessener Ø-Ertrag der letzten Jahre (kWh/kWp) × kWp,
 11	//    Degradation ab heute
 12	//  - Förderphase bis Ende des Jahres IBN + Förderdauer: feste Vergütung oder
 13	//    Marktprämie (anzulegender Wert wirkt als Untergrenze)
 14	//  - danach Marktwert Solar (Merchant) mit Steigerung, abzüglich
 15	//    Direktvermarktungskosten
 16	//  - Laufzeit bis Ende der technischen Nutzungsdauer – oder bis Ende des
 17	//    Pacht-/Dachvertrags, wenn keine Verlängerung gesichert ist
 18	//  - Kosten: Betriebskosten und Pacht (mit Inflation), optional
 19	//    Wechselrichtertausch, Rückbau-Rücklage im letzten Jahr
 20	//  - Ertragswert = Barwert der Cashflows; Spanne: Diskont ±1 Prozentpunkt
 21	//    kombiniert mit Ertrag ±5 %
 22	
 23	import { BESTAND, ERLOESE, FREIFLAECHE, PACHT, PHASEN, REGIONEN, regionById, npv, irr } from "../invest/markt.js";
 24	
 25	export const PHASE_BESTAND = PHASEN.find((p) => p.id === "cod");
 26	
 27	/** Grober Richtwert der Vergütung nach IBN-Jahr (nur Vorbelegung) */
 28	export function verguetungRichtwert(ibnJahr) {
 29	  return (BESTAND.verguetungRichtwerte.find((v) => ibnJahr <= v.bis) || BESTAND.verguetungRichtwerte.at(-1)).ct;
 30	}
 31	
 32	export const STANDARD = {
 33	  kwp: 2000,
 34	  ibnJahr: 2012,
 35	  modell: "fest", // fest | marktpraemie
 36	  verguetungCt: verguetungRichtwert(2012),
 37	  foerderJahre: BESTAND.foerderJahre,
 38	  ertragKwhKwp: 1000,
 39	  regionId: "de-sued",
 40	  typ: "freiflaeche", // freiflaeche | dach (nur für den Prognosevergleich)
 41	  degradation: BESTAND.degradation,
 42	  opexKwp: BESTAND.opexProKwp,
 43	  pachtJahr: 6000,
 44	  pachtEndeJahr: 2042,
 45	  pachtVerlaengerbar: true,
 46	  nutzungsdauer: BESTAND.nutzungsdauer,
 47	  wrTausch: true,
 48	  wrJahr: 2028,
 49	  wrProKwp: BESTAND.wechselrichterProKwp.mittel,
 50	  diskont: BESTAND.diskont.standard,
 51	  merchantCt: ERLOESE.merchantCt,
 52	  merchantSteigerung: ERLOESE.merchantSteigerung,
 53	  rueckbau: true,
 54	  kaufpreis: 0,
 55	};
 56	
 57	/** Cashflow-Reihe und Kennzahlen für eine Eingabe */
 58	export function rechneBestand(eingabe = {}) {
 59	  const e = { ...STANDARD, ...eingabe };
 60	  const start = BESTAND.bewertungsjahr;
 61	  const alter = start - e.ibnJahr; // Betriebsjahre bis zum Bewertungsjahr
 62	  const foerderEnde = e.ibnJahr + e.foerderJahre; // letztes Kalenderjahr mit Förderung (DE: IBN-Jahr + 20)
 63	  const technischEnde = e.ibnJahr + e.nutzungsdauer;
 64	  const ende = e.pachtVerlaengerbar ? technischEnde : Math.min(technischEnde, e.pachtEndeJahr);
 65	  const restJahre = Math.max(0, ende - start + 1);
 66	  const foerderRest = Math.max(0, Math.min(foerderEnde, ende) - start + 1);
 67	
 68	  const jahre = [];
 69	  for (let i = 0; i < restJahre; i++) {
 70	    const jahr = start + i;
 71	    const t = i + 1;
 72	    const kwh = e.kwp * e.ertragKwhKwp * Math.pow(1 - e.degradation, i);
 73	    const marktCt = e.merchantCt * Math.pow(1 + e.merchantSteigerung, i);
 74	    const gefoerdert = jahr <= foerderEnde;
 75	    const preisCt = gefoerdert ? (e.modell === "marktpraemie" ? Math.max(e.verguetungCt, marktCt) : e.verguetungCt) : marktCt - BESTAND.direktvermarktungCt;
 76	    const erloes = (kwh * preisCt) / 100;
 77	    const opex = e.kwp * e.opexKwp * Math.pow(1 + FREIFLAECHE.inflation, i);
 78	    const pacht = e.pachtJahr * Math.pow(1 + PACHT.indexierung, i);
 79	    const wr = e.wrTausch && jahr === e.wrJahr ? e.kwp * e.wrProKwp : 0;
 80	    const rueckbau = e.rueckbau && i === restJahre - 1 ? e.kwp * FREIFLAECHE.rueckbauProKwp : 0;
 81	    const cf = erloes - opex - pacht - wr - rueckbau;
 82	    jahre.push({ jahr, t, kwh, preisCt, gefoerdert, erloes, opex, pacht, wr, rueckbau, cf });
 83	  }
 84	
 85	  const cfs = [0, ...jahre.map((j) => j.cf)];
 86	  const wert = npv(e.diskont, cfs);
 87	  const wertBei = (diskont, ertragFaktor) =>
 88	    npv(diskont, [0, ...jahre.map((j) => j.cf + (j.erloes * (ertragFaktor - 1)))]);
 89	  const spanne = {
 90	    min: wertBei(e.diskont + 0.01, 0.95),
 91	    max: wertBei(Math.max(e.diskont - 0.01, 0.001), 1.05),
 92	  };
 93	
 94	  // Barwert-Anteil der Förderphase
 95	  const bwFoerder = jahre.filter((j) => j.gefoerdert).reduce((s, j) => s + j.cf / Math.pow(1 + e.diskont, j.t), 0);
 96	
 97	  // Prognosevergleich: Ertrag laut Region (Freifläche optimal bzw. Dach) im heutigen Alter
 98	  const region = regionById(e.regionId);
 99	  const typFaktor = e.typ === "dach" ? 0.93 : 1;
100	  const prognose = region.ertrag * typFaktor * Math.pow(1 - e.degradation, Math.max(alter, 0));
101	  const performance = prognose > 0 ? e.ertragKwhKwp / prognose : null;
102	
103	  const wertProKwp = e.kwp > 0 ? wert / e.kwp : 0;
104	  const band = PHASE_BESTAND.preisProKwp;
105	  const einordnung = wertProKwp < band.min ? "unter" : wertProKwp > band.max ? "ueber" : "in";
106	
107	  const kaufIrr = e.kaufpreis > 0 ? irr([-e.kaufpreis, ...jahre.map((j) => j.cf)], -0.3, 1) : null;
108	
109	  return {
110	    eingabe: e,
111	    start,
112	    alter,
113	    foerderEnde,
114	    technischEnde,
115	    ende,
116	    restJahre,
117	    foerderRest,
118	    jahre,
119	    wert,
120	    wertProKwp,
121	    spanne,
122	    spanneProKwp: { min: spanne.min / e.kwp, max: spanne.max / e.kwp },
123	    anteilFoerderung: wert > 0 ? bwFoerder / wert : null,
124	    summeCf: jahre.reduce((s, j) => s + j.cf, 0),
125	    erloesJahr1: jahre[0]?.erloes || 0,
126	    cfJahr1: jahre[0]?.cf || 0,
127	    prognose,
128	    performance,
129	    einordnung,
130	    band,
131	    kaufIrr,
132	  };
133	}
134	
135	/**
136	 * Sensitivität: Wert je kWp bei verändertem Diskontsatz (Zeilen, Prozent-
137	 * punkte) und Marktpreis nach Förderende (Spalten, relativ).
138	 */
139	export function sensitivitaet(eingabe = {}, schritteDiskont = [-0.015, -0.0075, 0, 0.0075, 0.015], schrittePreis = [-0.3, -0.15, 0, 0.15, 0.3]) {
140	  const e = { ...STANDARD, ...eingabe };
141	  return schritteDiskont.map((dd) => ({
142	    diskont: dd,
143	    wertDiskont: e.diskont + dd,
144	    zellen: schrittePreis.map((dp) => {
145	      const r = rechneBestand({ ...e, diskont: Math.max(e.diskont + dd, 0.001), merchantCt: e.merchantCt * (1 + dp) });
146	      return { preis: dp, wertProKwp: r.wertProKwp };
147	    }),
148	  }));
149	}
150	
151	/** Tornado: Wirkung einzelner Annahmen auf den Ertragswert (€) */
152	export function tornado(eingabe = {}) {
153	  const e = { ...STANDARD, ...eingabe };
154	  const basis = rechneBestand(e).wert;
155	  const faelle = [
156	    { id: "ertrag", label: "Ertrag ±10 %", tief: { ertragKwhKwp: e.ertragKwhKwp * 0.9 }, hoch: { ertragKwhKwp: e.ertragKwhKwp * 1.1 } },
157	    { id: "diskont", label: "Diskontsatz ±1 Pp.", tief: { diskont: e.diskont + 0.01 }, hoch: { diskont: Math.max(e.diskont - 0.01, 0.001) } },
158	    { id: "markt", label: "Marktpreis nach Förderung ±25 %", tief: { merchantCt: e.merchantCt * 0.75 }, hoch: { merchantCt: e.merchantCt * 1.25 } },
159	    { id: "opex", label: "Betriebskosten ±20 %", tief: { opexKwp: e.opexKwp * 1.2 }, hoch: { opexKwp: e.opexKwp * 0.8 } },
160	    { id: "laufzeit", label: "Nutzungsdauer ±5 Jahre", tief: { nutzungsdauer: e.nutzungsdauer - 5 }, hoch: { nutzungsdauer: e.nutzungsdauer + 5 } },
161	  ];
162	  return faelle
163	    .map((f) => {
164	      const tief = rechneBestand({ ...e, ...f.tief }).wert - basis;
165	      const hoch = rechneBestand({ ...e, ...f.hoch }).wert - basis;
166	      return { id: f.id, label: f.label, tief, hoch, spanne: Math.abs(hoch - tief) };
167	    })
168	    .sort((a, b) => b.spanne - a.spanne);
169	}
170	
171	export { REGIONEN };
172	
173	/* ------------------------------------------------------------------ */
174	/* Selbsttest: node src/lib/rechner/bestandsanlage.js                  */
175	/* ------------------------------------------------------------------ */
176	
177	export function selbsttest() {
178	  const fehler = [];
179	  const pruefe = (ok, text) => {
180	    if (!ok) fehler.push(text);
181	  };
182	
183	  const r = rechneBestand();
184	  pruefe(r.foerderEnde === 2032, "IBN 2012 + 20 Jahre Förderung → letztes Förderjahr 2032");
185	  pruefe(r.foerderRest === 2032 - BESTAND.bewertungsjahr + 1, "Förder-Restlaufzeit ab Bewertungsjahr");
186	  pruefe(r.ende === 2042, "Nutzungsdauer 30 Jahre → Ende 2042");
187	  pruefe(r.jahre.length === 2042 - BESTAND.bewertungsjahr + 1, "Anzahl Restjahre");
188	  pruefe(r.jahre[0].preisCt === STANDARD.verguetungCt, "Förderphase mit fester Vergütung");
189	  pruefe(!r.jahre.at(-1).gefoerdert, "am Ende Merchant");
190	  pruefe(r.wert > 0 && r.spanne.min < r.wert && r.wert < r.spanne.max, "Wert liegt in der Spanne");
191	  pruefe(r.jahre.find((j) => j.jahr === STANDARD.wrJahr).wr > 0, "Wechselrichtertausch im gewählten Jahr");
192	
193	  const cfs = [0, ...r.jahre.map((j) => j.cf)];
194	  pruefe(Math.abs(npv(STANDARD.diskont, cfs) - r.wert) < 1e-6, "Ertragswert = npv der Cashflows");
195	
196	  const kauf = rechneBestand({ kaufpreis: r.wert });
197	  pruefe(Math.abs(kauf.kaufIrr - STANDARD.diskont) < 0.001, "Kaufpreis = Ertragswert → Käufer-IRR = Diskontsatz");
198	
199	  const teurer = rechneBestand({ diskont: 0.08 });
200	  pruefe(teurer.wert < r.wert, "höherer Diskont senkt den Wert");
201	  const pachtKurz = rechneBestand({ pachtVerlaengerbar: false, pachtEndeJahr: 2035 });
202	  pruefe(pachtKurz.ende === 2035 && pachtKurz.wert < r.wert, "kurzer Pachtvertrag ohne Verlängerung begrenzt Laufzeit und Wert");
203	  const mp = rechneBestand({ modell: "marktpraemie", verguetungCt: 3, merchantCt: 6, merchantSteigerung: 0 });
204	  pruefe(Math.abs(mp.jahre[0].preisCt - 6) < 1e-9, "Marktprämie: höherer Marktwert bleibt");
205	  const alt = rechneBestand({ ibnJahr: 1995, nutzungsdauer: 30 });
206	  pruefe(alt.restJahre === 0 && alt.wert === 0, "Anlage jenseits der Nutzungsdauer hat keinen Ertragswert");
207	
208	  pruefe(verguetungRichtwert(2010) === 27 && verguetungRichtwert(2024) === 5, "Richtwerte Vergütung");
209	  const m = sensitivitaet();
210	  pruefe(m.length === 5 && m[0].zellen.length === 5, "Sensitivitätsmatrix 5 × 5");
211	  pruefe(m[0].zellen[4].wertProKwp > m[4].zellen[0].wertProKwp, "niedriger Diskont + hoher Preis schlägt das Gegenteil");
212	  const tor = tornado();
213	  pruefe(tor.length === 5 && tor[0].spanne >= tor[4].spanne, "Tornado sortiert");
214	
215	  return { fehler, beispiel: r };
216	}
217	
218	if (typeof process !== "undefined" && process.argv?.[1] && /bestandsanlage\.js$/.test(process.argv[1].replace(/\\/g, "/"))) {
219	  const { fehler, beispiel: r } = selbsttest();
220	  console.log(
221	    `Beispiel 2 MWp, IBN 2012, ${r.eingabe.verguetungCt} ct bis ${r.foerderEnde}: Ertragswert ${Math.round(r.wert)} € ` +
222	      `(${Math.round(r.wertProKwp)} €/kWp, Spanne ${Math.round(r.spanneProKwp.min)}–${Math.round(r.spanneProKwp.max)} €/kWp), ` +
223	      `Förderanteil ${(r.anteilFoerderung * 100).toFixed(0)} %, Performance ${(r.performance * 100).toFixed(0)} %, Einordnung ${r.einordnung}`
224	  );
225	  if (fehler.length) {
226	    console.error("FEHLER:\n- " + fehler.join("\n- "));
227	    process.exit(1);
228	  }
229	  console.log("Selbsttest bestandsanlage.js: alle Prüfungen bestanden.");
230	}
  1	// Bewertung – acht Werttreiber und Beispielvergleich (gleiche Anlage, anderes Baujahr) als Spannen-Grafik + Tabelle
  2	import Link from "next/link";
  3	import { Activity, ArrowRight, CalendarClock, Camera, FileCheck2, LineChart, ScrollText, TrendingDown, Wrench } from "lucide-react";
  4	import SectionHeading from "@/components/ui/SectionHeading";
  5	import Reveal from "@/components/ui/Reveal";
  6	import Aufbau, { aufbau } from "@/components/Flaeche/Seite/Aufbau";
  7	import { fmt, fmtMio } from "@/lib/rechner/annahmen";
  8	
  9	/** Wert je kWp der Beispiele auf einer Skala, übliche Spanne als Band */
 10	function SpannenGrafik({ beispiele, band }) {
 11	  const werte = beispiele.map((b) => b.r.wertProKwp);
 12	  const lo = Math.min(0, ...werte);
 13	  const hi = Math.max(band.max, ...werte) * 1.22;
 14	  const pos = (v) => `${((v - lo) / (hi - lo)) * 100}%`;
 15	  return (
 16	    <div className="mt-8">
 17	      <div className="relative ml-[4.5rem] h-6 sm:ml-24">
 18	        <span className="absolute top-0 -translate-x-1/2 whitespace-nowrap text-[11.5px] font-semibold text-ov-700" style={{ left: `calc((${pos(band.min)} + ${pos(band.max)}) / 2)` }}>
 19	          übliche Spanne {fmt(band.min)}–{fmt(band.max)} €/kWp
 20	        </span>
 21	      </div>
 22	      <Aufbau as="ul" schritt={140} className="space-y-3">
 23	        {beispiele.map(({ jahr, ct, r }, i) => (
 24	          <li key={jahr} className="grid grid-cols-[4.5rem_minmax(0,1fr)] items-center gap-0 sm:grid-cols-[6rem_minmax(0,1fr)]">
 25	            <span className="text-[13px] leading-tight text-ink-600">
 26	              <strong className="block font-display text-[15px] text-ink-900">IBN {jahr}</strong>
 27	              {fmt(ct, 1)} ct
 28	            </span>
 29	            <span className="relative block h-9 rounded-xl bg-sand-50 ring-1 ring-inset ring-ink-100">
 30	              <span aria-hidden="true" className="absolute inset-y-0 bg-ov-100/80" style={{ left: pos(band.min), width: `calc(${pos(band.max)} - ${pos(band.min)})` }} />
 31	              <span aria-hidden="true" className={`absolute inset-y-1.5 left-1.5 rounded-lg ${aufbau.wachsen} ${r.einordnung === "ueber" ? "bg-ov-600" : r.einordnung === "unter" ? "bg-navy-400" : "bg-ov-400"}`} style={{ width: `calc(${pos(r.wertProKwp)} - 0.375rem)`, "--i": i }} />
 32	              <span className={`ov-num absolute inset-y-0 flex items-center whitespace-nowrap pl-2 text-[13px] font-bold text-ink-900 ${aufbau.ein}`} style={{ left: pos(r.wertProKwp), "--i": i, "--ein-start": "550ms" }}>
 33	                {fmt(r.wertProKwp)} €
 34	              </span>
 35	            </span>
 36	          </li>
 37	        ))}
 38	      </Aufbau>
 39	    </div>
 40	  );
 41	}
 42	
 43	export default function Bewertung({ beispiele, band, bestand, merchantCt, stand }) {
 44	  const treiber = [
 45	    { icon: CalendarClock, title: "Restlaufzeit der Förderung", text: "In Deutschland 20 Jahre plus Rest des Inbetriebnahmejahres. Hohe Alttarife tragen oft den Großteil des Werts – bis zum letzten Förderjahr." },
 46	    { icon: Activity, title: "Ertragshistorie vs. Prognose", text: "Gemessene Jahre gegen Einstrahlung und Gutachten. Minderertrag hat Ursachen – behebbar oder dauerhaft." },
 47	    { icon: TrendingDown, title: "Degradation", text: `Ältere Module verlieren meist rund ${fmt(bestand.degradation * 100, 1)} % pro Jahr, einzelne Modultypen deutlich mehr – Kennlinienmessungen zeigen es.` },
 48	    { icon: Wrench, title: "Wechsel­richter­tausch", text: `Nach ${bestand.wechselrichterJahre.min}–${bestand.wechselrichterJahre.max} Jahren meist fällig, grob ${fmt(bestand.wechselrichterProKwp.min)}–${fmt(bestand.wechselrichterProKwp.max)} €/kWp. Steht er bevor, mindert er den Kaufpreis.` },
 49	    { icon: ScrollText, title: "Pacht- und Dachvertrag", text: "Endet der Vertrag vor der technischen Nutzungsdauer, endet auch der Cashflow. Eine gesicherte Verlängerung hebt den Wert." },
 50	    { icon: Camera, title: "Technische Due Diligence", text: "Begehung, Thermografie per Drohne, Kennlinien, Isolationsmessung, Zustand von Unterkonstruktion, Kabeln und Station." },
 51	    { icon: FileCheck2, title: "Anlagenzertifikat & Netz", text: "Anlagen- bzw. Einheitenzertifikat, Netzanschlussvertrag, Konformitätsnachweise, Registrierung im Marktstammdatenregister." },
 52	    { icon: LineChart, title: "Marktpreis nach Förderende", text: `Danach zählt der Solar-Marktwert – wir rechnen vorsichtig mit ${fmt(merchantCt, 1)} ct/kWh. Ein PPA kann das Risiko begrenzen.` },
 53	  ];
 54	
 55	  return (
 56	    <section data-abschnitt="bewertung" aria-labelledby="bewertung-titel" className="bg-sand-50 py-20 md:py-28">
 57	      <div className="ov-container">
 58	        <SectionHeading
 59	          eyebrow="Bewertung"
 60	          title={<span id="bewertung-titel">Was den Wert einer laufenden Anlage bestimmt.</span>}
 61	          lead="Grundlage ist der Ertragswert (DCF): alle künftigen Einnahmen und Ausgaben, Jahr für Jahr, abgezinst mit der Renditeerwartung des Käufers. Diese acht Punkte bewegen ihn am stärksten."
 62	        />
 63	
 64	        <ol className="mt-10 grid gap-px overflow-hidden rounded-3xl bg-ink-200/70 ring-1 ring-ink-200/70 sm:grid-cols-2 md:mt-12 lg:grid-cols-4">
 65	          {treiber.map((t, i) => (
 66	            <Reveal as="li" key={t.title} delay={(i % 4) * 60} className="flex flex-col bg-white p-6">
 67	              <div className="flex items-center justify-between">
 68	                <span className="flex h-10 w-10 items-center justify-center rounded-xl bg-ov-50 text-ov-600 ring-1 ring-ov-200">
 69	                  <t.icon aria-hidden="true" className="h-[18px] w-[18px]" />
 70	                </span>
 71	                <span aria-hidden="true" className="ov-num font-display text-[13px] font-bold text-ink-300">0{i + 1}</span>
 72	              </div>
 73	              <h3 className="mt-4 font-display text-[17px] font-bold leading-snug text-ink-900">{t.title}</h3>
 74	              <p className="mt-2 text-[14px] leading-relaxed text-ink-600">{t.text}</p>
 75	            </Reveal>
 76	          ))}
 77	        </ol>
 78	
 79	        {/* Drei Beispiele */}
 80	        <Reveal className="mt-8 overflow-hidden rounded-[1.75rem] bg-white shadow-e2 ring-1 ring-ink-200/70">
 81	          <div>
 82	            <div className="grid grid-cols-[minmax(0,1fr)] gap-x-12 p-6 md:p-8 lg:grid-cols-[minmax(0,0.9fr)_minmax(0,1.1fr)] lg:items-center">
 83	              <div>
 84	              <p className="text-[12.5px] font-semibold uppercase tracking-[0.12em] text-ov-700">Beispielrechnung</p>
 85	              <h3 className="mt-2 font-display text-[22px] font-bold leading-tight text-ink-900">Gleiche Anlage, anderes Baujahr – anderer Wert</h3>
 86	              <p className="mt-3 max-w-2xl text-[14.5px] leading-relaxed text-ink-600">
 87	                2 MWp Freifläche in Süddeutschland, 1.000 kWh/kWp gemessen, Pacht 6.000 €/Jahr, Wechselrichtertausch 2029, Diskontsatz {fmt(bestand.diskont.standard * 100, 1)} %, Bewertung ab {bestand.bewertungsjahr}.
 88	              </p>
 89	              </div>
 90	              <div>
 91	                <SpannenGrafik beispiele={beispiele} band={band} />
 92	                <p className="mt-3 text-[12.5px] text-ink-500">Ertragswert je kWp · Band: übliche Spanne für Bestandsanlagen</p>
 93	              </div>
 94	            </div>
 95	            <div className="border-t border-ink-100 bg-sand-50/60 p-6 md:p-8">
 96	              <div tabIndex={0} role="region" aria-label="Beispielbewertungen" className="overflow-x-auto rounded focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-500">
